  [1219058] = { "Il Military Quarter è potenziato. Durante il combattimento verranno impartiti ordini a caso. Eseguili, o subisci le conseguenze!", "Il Military Quarter è potenziato. Durante il combattimento verranno impartiti ordini a caso. Obbedisci, o ne subirai le conseguenze!", 0xb3b003ec, 0xb3b003ec, "uu" },
  [1219059] = { "⟦Flash of Light=Lampo di Luce⟧ Grado $N1 e ⟦Holy Light=Luce Sacra⟧ Grado $N2 e Grado $N3 hanno una probabilità del $N4% di infondere ⟦Holy Power=Potere Sacro⟧ nel bersaglio.", nil, 0x517a6b4f, nil, "um" },
  [1219060] = { "Fai come ti viene detto!", "Fai come ti viene detto!", 0xbc98b987, 0xbc98b987, "uu" },
  [1219072] = { "Aumenta le cure del $N1% e i danni inflitti del $N2%.", "Aumenta le cure del $N1% e i danni inflitti del $N2%.", 0x1829799b, 0x1829799b, "uu" },
  [1219073] = { "I danni inflitti da Creeping Darkness sono aumentati del $N1%.", nil, 0x05f1a457, nil, "um" },
  [1219083] = { "Infligge $N1 danni da ombra agli attaccanti in mischia. Genera una minaccia pari al doppio dei danni inflitti.", nil, 0x5d6dd2c9, nil, "um" },
  [1219085] = { "Costretto a marciare. Dura finché non avrai imparato la lezione!", "Marcia forzata. Dura finché non avrai imparato la lezione!", 0x5ecd5bb8, 0x5ecd5bb8, "uu" },
  [1219090] = { "Silenzia il bersaglio per $D1.", "Silenziato.", 0x2ab5d0e3, 0x20816e34, "uu" },
  [1219093] = { "Afferra un filo dell'anima del nemico per trascinarne verso di te la forma fisica. Non utilizzabile su nemici di livello superiore a $N1 o contrassegnati come boss.", nil, 0x56e8dfe3, nil, "um" },
  [1219098] = { "Il bersaglio del tuo Faro di Luce subisce il $N1% di danni in meno dai nemici Non Morti.", nil, 0xe8a6ff2d, nil, "um" },
  [1219099] = { { "Punisce fino a $N1 nemici vicini con una sferzata d'ombra, infliggendo $N2 danni a ciascuno.\n\nFendente d'Ombra beneficia della maggior parte dei talenti e degli effetti di cui beneficia ⟦Shadow Bolt=Dardo d'Ombra⟧, e li attiva allo stesso modo.\n\nColpire un bersaglio con Fendente d'Ombra ti conferisce anche $N3 danni magici per ogni punto di abilità in Difesa oltre $N4. Dura $D1.", "Punisce fino a $N1 nemici vicini con una sferzata d'ombra, infliggendo $N2 danni a ciascuno.\n\nFendente d'Ombra beneficia della maggior parte dei talenti e degli effetti di cui beneficia ⟦Shadow Bolt=Dardo d'Ombra⟧, e li attiva allo stesso modo.", shape = { "5/1", "2/0" } }, nil, 0xae277fcd, nil, "um" },
  [1219101] = { "Il tuo prossimo incantesimo Evocazione: Imp, Evocazione: Ombra del Vuoto, Evocazione: Succube, Evocazione: Incubus, Evocazione: Vilsegugio o Evocazione: Vilguardia ha il tempo di lancio ridotto di $D1 e non costa frammenti d'anima né mana.", "Tempo di lancio delle evocazioni di Imp, Ombra del Vuoto, Succube, Incubus, Vilsegugio e Felguard ridotto di $D1. Costi in mana e in frammenti d'anima ridotti del $N2%.", 0x59404b53, 0xbe3d1d6a, "uu" },
  [1219108] = { "Il Military Quarter è potenziato. Durante il combattimento verranno impartiti ordini a caso. Eseguili, o subisci le conseguenze!", "Il Military Quarter è potenziato. Durante il combattimento verranno impartiti ordini a caso. Obbedisci, o ne subirai le conseguenze!", 0xb3b003ec, 0xb3b003ec, "uu" },
  [1219110] = { "Afferra un filo dell'anima del nemico per trascinarne verso di te la forma fisica. Non utilizzabile su nemici di livello superiore a $N1 o contrassegnati come boss.", nil, 0x731b5176, nil, "um" },
  [1219111] = { "Afferra un filo dell'anima del nemico per trascinarne verso di te la forma fisica. Non utilizzabile su nemici di livello superiore a $N1 o contrassegnati come boss.", nil, 0x731b5176, nil, "um" },
  [1219114] = { "Il Plague Quarter è potenziato. Nelle vicinanze spunteranno a caso funghi rinvigorenti, che però esploderanno quando giungeranno a maturazione.", "Il Plague Quarter è potenziato. Funghi corroboranti spuntano a caso nelle vicinanze, ma esplodono quando arrivano a maturazione.", 0x62ed26b1, 0x62ed26b1, "uu" },
  [1219121] = { "Infligge Piaga del Sangue al bersaglio nemico, che subisce $N1 danni da ombra ogni $D1 per $D2.", "Subisci $N1 danni da ombra ogni $D1.", 0x8269b84e, 0xf8147610, "uu" },
  [1219124] = { "Infligge Febbre del Gelo al bersaglio nemico, che subisce $N1 danni da gelo ogni $D1 per $D2.", "$N1 danni da gelo subiti ogni $D1.", 0xa3a0979d, 0x9934110a, "uu" },
  [1219150] = { "Aumenta del $N1% la velocità d'attacco e di lancio degli incantesimi. Aumenta del $N2% i danni da natura subiti.", "Aumenta del $N1% la velocità d'attacco e di lancio degli incantesimi. Aumenta del $N2% i danni da natura subiti.", 0x8792b770, 0x8792b770, "uu" },
  [1219153] = { "Marchia un nemico. Ogni volta che infligge danni, il bersaglio colpito viene curato del $N1% della sua salute massima. Dura $D1 o fino a $N3 colpi.\n\nGli accumuli non si esauriscono sui bersagli Non Morti. Su un bersaglio può essere attivo un solo Marchio del Sangue alla volta.", "I colpi di questo bersaglio rigenerano il $N1% della salute.", 0xbc0a2ae6, 0x59c22f12, "uu" },
  [1219161] = { "Marchia un nemico. Ogni volta che infligge danni, il bersaglio colpito viene curato del $N1% della sua salute massima. Dura $D1 o fino a $N3 colpi.\n\nGli accumuli non si esauriscono sui bersagli Non Morti. Su un bersaglio può essere attivo un solo Marchio del Sangue alla volta.", nil, 0x731b9273, nil, "um" },
  [1219176] = { "Disintegra il bersaglio, infliggendo $N1 danni.\n\nPiaga del Sangue e Febbre del Gelo presenti sul bersaglio aumentano ciascuna i danni inflitti del $N2%.", nil, 0xeb4ba160, nil, "um" },
  [1219178] = { "Disintegra il bersaglio, infliggendo $N1 danni.\n\nPiaga del Sangue e Febbre del Gelo presenti sul bersaglio aumentano ciascuna i danni inflitti del $N2%.", nil, 0x731b937c, nil, "um" },
  [1219189] = { "Aumenta del $N1% i danni inflitti da Tempesta Divina.", nil, 0x077c9f47, nil, "um" },
  [1219191] = { "Riduce del $N1% il tempo di lancio di ⟦Holy Wrath=Ira Sacra⟧, del $N2% il suo tempo di recupero e del $N3% il suo costo in mana.", nil, 0x62b1f42d, nil, "um" },
  [1219193] = { "⟦Crusader Strike=Assalto del Crociato⟧, Tempesta Divina, Esorcismo e ⟦Holy Wrath=Ira Sacra⟧ infliggono ai Non Morti danni aumentati in misura pari alla loro probabilità di critico.", nil, 0x921a97cd, nil, "um" },
  [1219194] = { "Il Plague Quarter è potenziato. Nelle vicinanze spunteranno a caso funghi rinvigorenti, che però esploderanno quando giungeranno a maturazione.", "Il Plague Quarter è potenziato. Funghi corroboranti spuntano a caso nelle vicinanze, ma esplodono quando arrivano a maturazione.", 0x62ed26b1, 0x62ed26b1, "uu" },
  [1219195] = { "Il Plague Quarter è potenziato. Nelle vicinanze spunteranno a caso funghi rinvigorenti, che però esploderanno quando giungeranno a maturazione.", "Il Plague Quarter è potenziato. Funghi corroboranti spuntano a caso nelle vicinanze, ma esplodono quando arrivano a maturazione.", 0x62ed26b1, 0x62ed26b1, "uu" },
  [1219205] = { "Imposizione della Sfida non manca mai il bersaglio, e la probabilità che venga schivata o parata è ridotta del $N1%.", nil, 0x3f61ede0, nil, "um" },
  [1219206] = { "Provoca il bersaglio, inducendolo ad attaccarti, ma non ha effetto se il bersaglio ti sta già attaccando.\n\nFinché conosci questa abilità, il bonus di minaccia di ⟦Righteous Fury=Giusta Furia⟧ sale al $N1% e ⟦Righteous Fury=Giusta Furia⟧ ti fa ottenere, quando vieni curato da altri, mana pari al $N2% della cura ricevuta. Inoltre, mentre ⟦Righteous Fury=Giusta Furia⟧ è attiva, i danni che portano la tua salute sotto il $N3% sono ridotti del $N4%. ⟦Righteous Fury=Giusta Furia⟧ resta attiva finché non viene annullata.", "Provocato.", 0x45b57cee, 0x36f56123, "uu" },
  [1219225] = { "Riduce di $D1 il tempo di recupero di ⟦Divine Protection=Protezione Divina⟧ e di $D2 quello di Ira Vendicatrice.", nil, 0x5d5a9d19, nil, "um" },
  [1219226] = { "Quando i danni di un nemico Non Morto portano la tua salute sotto il $N1%, l'effetto di Imposizione della Sfida e ⟦Righteous Fury=Giusta Furia⟧ ora riduce quei danni del $N2%.", nil, 0xf41a51c9, nil, "um" },
  [1219229] = { "Il Construct Quarter è stato potenziato. Alcuni giocatori scelti a caso vengono colpiti da fulmini energizzanti.", "Il Construct Quarter è stato potenziato. Alcuni giocatori scelti a caso vengono colpiti da fulmini energizzanti.", 0x09e739cf, 0x09e739cf, "uu" },
