  [1219503] = { "Riduce del $N1% le tue dimensioni e la minaccia che generi per $D1.", "Dimensioni e minaccia generata ridotte del $N1%.", 0xf1bbff24, 0xce0fe7d9, "uu" },
  [1219506] = { "Rigenera $N1 mana.", nil, 0x09fdd6de, nil, "um" },
  [1219507] = { "Aggiunge in modo permanente a un oggetto per le spalle un aumento fino a $N1 delle cure prodotte da incantesimi ed effetti magici, e aumenta inoltre la rigenerazione del mana di $N2 mana ogni $D1.", nil, 0xddab39b3, nil, "um" },
  [1219510] = { "Aggiunge in modo permanente a un oggetto per le spalle un aumento fino a $N1 dei danni e delle cure prodotti da incantesimi ed effetti magici, e aumenta inoltre del $N2% la probabilità di infliggere un colpo critico.", nil, 0x314de3bd, nil, "um" },
  [1219511] = { "Aggiunge in modo permanente a un oggetto per le spalle un aumento della Tempra di $N1 e della Difesa di $N2.", nil, 0x54c249bc, nil, "um" },
  [1219512] = { "Aggiunge in modo permanente a un oggetto per le spalle un aumento della potenza d'attacco di $N1, e aumenta inoltre del $N2% la probabilità di infliggere un colpo critico.", nil, 0x811e608c, nil, "um" },
  [1219513] = { "Aumenta fino a $N2 le cure prodotte dai prossimi $N1 incantesimi per $D1.", "Incantesimi di cura aumentati fino a $N1.", 0x9695f8e3, 0xd754af7b, "uu" },
  [1219515] = { "Aumenta fino a $N1 i danni e le cure di incantesimi ed effetti magici per $D1.", "Danni e cure degli incantesimi aumentati fino a $N1.", 0xc0d35181, 0xce30f511, "uu" },
  [1219519] = { "Aumenta la potenza d'attacco di $N1 per $D1.", "Potenza d'attacco aumentata di $N1.", 0xb593685a, 0x2905f15b, "uu" },
  [1219520] = { "Aumenta di $N1 l'indice di blocco dello scudo per $D1.", "Indice di blocco aumentato di $N1.", 0xe7882b6e, 0x64e8286f, "uu" },
  [1219521] = { "+$N1 potenza d'attacco contro Non Morti e demoni. Permette inoltre di ottenere Pietre del Flagello per conto dell'⟦Argent Dawn=Alba d'Argento⟧.", nil, 0xdbacf565, nil, "um" },
  [1219522] = { "Aumenta fino a $N1 i danni inflitti a Non Morti e Demoni da incantesimi ed effetti magici. Permette di ottenere le Pietre del Flagello per conto dell'⟦Argent Dawn=Alba d'Argento⟧.", nil, 0xc1a76244, nil, "um" },
  [1219539] = { "Libera il tuo potenziale all'interno di Naxxramas, aumentando i tuoi danni del $N1% e la tua salute del $N2% per ogni oggetto Consacrato indossato. (Indossare più di $N3 oggetti Consacrati non dà alcun beneficio aggiuntivo)", "Libera il tuo potenziale all'interno di Naxxramas, aumentando i tuoi danni del $N1% e la tua salute del $N2% per ogni oggetto Consacrato indossato.", 0x239ff9c8, 0xc451f1c1, "uu" },
  [1219540] = { "Provocazione non manca mai il bersaglio, e la probabilità che venga schivata o parata è ridotta del $N1%.", nil, 0xd243841f, nil, "um" },
  [1219541] = { "Costringe il bersaglio ad attaccarti, ma non ha effetto se il bersaglio ti sta già attaccando.", nil, 0x71de38fd, nil, "um" },
  [1219543] = { "Riduce di $D1 il tempo di recupero di ⟦Shield Wall=Muro di Scudi⟧ e di $D2 quello di Avventatezza. Avventatezza ora può essere usata in qualsiasi postura e non aumenta i danni subiti.", nil, 0x4c47736c, nil, "um" },
  [1219544] = { "Quando subisci danni da un nemico Non Morto, la durata rimanente di ⟦Last Stand=Ultima Difesa⟧ attiva torna a $D1.", nil, 0xbef9d539, nil, "um" },
  [1219548] = { "Libera il tuo potenziale all'interno di Naxxramas, aumentando le tue cure del $N1% e la tua salute del $N2% per ogni oggetto Consacrato indossato. (Indossare più di $N3 oggetti Consacrati non dà alcun beneficio aggiuntivo)", "Libera il tuo potenziale all'interno di Naxxramas, aumentando le tue cure del $N1% e la tua salute del $N2% per ogni oggetto Consacrato indossato.", 0xfb50752c, 0x3a3efb98, "uu" },
  [1219552] = { "Aumenta fino a $N2 i danni e le cure prodotti da incantesimi ed effetti magici di tutti i membri del gruppo entro $N1 m. Questo effetto specifico non è cumulabile da più fonti.", "Aumenta fino a $N1 i danni e le cure prodotti da incantesimi ed effetti magici. Questo effetto specifico non è cumulabile da più fonti.", 0x0c3354b0, 0xc9de4c90, "uu" },
  [1219553] = { "Aumenta fino a $N1 le cure prodotte e fino a $N2 i danni inflitti da tutti gli incantesimi ed effetti magici di tutti i membri del gruppo entro $N3 m. Questo effetto specifico non è cumulabile da più fonti.", "Aumenta fino a $N1 le cure prodotte e fino a $N2 i danni inflitti da tutti gli incantesimi ed effetti magici. Questo effetto specifico non è cumulabile da più fonti.", 0x828eded3, 0x0de1dc02, "uu" },
  [1219557] = { "Aumenta del $N2% la velocità di lancio degli incantesimi di tutti i membri del gruppo entro $N1 m. Questo specifico effetto non si cumula da più fonti.", "Aumenta del $N1% la velocità di lancio degli incantesimi. Questo effetto specifico non è cumulabile da più fonti.", 0x251f0459, 0x05f89473, "uu" },
  [1219558] = { "Aumenta del $N2% la probabilità di critico con gli incantesimi di tutti i membri del gruppo entro $N1 m. Questo specifico effetto non si cumula da più fonti.", "Aumenta del $N2% la probabilità di critico con gli incantesimi di tutti i membri del gruppo entro $N1 m. Questo effetto specifico non è cumulabile da più fonti.", 0x0490bbea, 0x0490bbea, "uu" },
  [1219577] = { "Incanta in modo permanente un oggetto per la mano secondaria per aggiungere $N1 all'Intelletto.", nil, 0x60a9b17f, nil, "um" },
  [1219578] = { "Incanta in modo permanente un oggetto per la mano secondaria per aggiungere $N1 allo Spirito.", nil, 0xe62ca978, nil, "um" },
  [1219579] = { "Incanta in modo permanente un oggetto per la mano secondaria per aggiungere $N1 all'Intelletto e $N2 allo Spirito.", nil, 0x0a28ddd8, nil, "um" },
  [1219580] = { "Incanta in modo permanente un'arma a due mani per aggiungere $N1 alla potenza magica.", nil, 0xe3aaecc8, nil, "um" },
  [1219581] = { "Incanta in modo permanente uno scudo per aggiungere $N1 alla Tempra.", nil, 0x4e82b193, nil, "um" },
  [1219587] = { "Incanta in modo permanente un mantello per aggiungere $N1 all'Agilità.", nil, 0x812f211c, nil, "um" },
  [1219706] = { "Rigenera $N1 energia.", "$N1 energia rigenerata.", 0x4da5dee5, 0x4f24baef, "uu" },
  [1219707] = { "Genera $N1 rabbia.", "$N1 rabbia generata.", 0x61c09340, 0x562c792a, "uu" },
  [1219708] = { "Rigenera $N1 mana.", "$N1 mana rigenerato.", 0x09fdd6de, 0xffb4963e, "uu" },
  [1219729] = { "Subisci ingenti danni da gelo quando quest'aura scade, ripartiti tra tutti gli alleati vicini.", "Subisci ingenti danni da gelo quando questa aura scade, ripartiti tra tutti gli alleati vicini.", 0xa9c281f1, 0xa9c281f1, "uu" },
  [1219732] = { "Subisci ingenti danni da gelo quando quest'aura scade, ripartiti tra tutti gli alleati vicini.", "Subisci ingenti danni da gelo quando questa aura scade, ripartiti tra tutti gli alleati vicini.", 0xa9c281f1, 0xa9c281f1, "uu" },
  [1219740] = { "Infondi in modo permanente nei tuoi spallacci la Soul of the Tactician:\n\nDopo aver cambiato postura, il costo in rabbia della tua prossima abilità offensiva si riduce di $N1.", nil, 0xdf824ef3, nil, "um" },
  [1219741] = { "Infligge $N1 danni da ombra ogni $D1. Riduce la velocità di movimento del $N3%.", "Infligge $N1 danni da ombra ogni $D1. Velocità di movimento ridotta del $N3%.", 0x74a97ae9, 0x74a97ae9, "uu" },
  [1219742] = { "Infondi in modo permanente nei tuoi spallacci la Soul of the War Veteran:\n\nPer $D1 dopo aver lasciato una postura, puoi usare le abilità che la richiedono come se fossi ancora in quella postura.", nil, 0x5f737b0f, nil, "um" },
  [1219743] = { "Infondi in modo permanente nei tuoi spallacci la Soul of the Battle Forecaster:\n\nPer i primi $D1 dopo aver attivato una postura, puoi ottenere un beneficio aggiuntivo:\n\nPostura da Battaglia/Gladiator Stance: danni inflitti aumentati del $N2%.\n\nPostura da Berserker: probabilità di critico aumentata del $N3%.\n\nPostura da Difesa: danni fisici subiti ridotti del $N4%.", nil, 0x54969ff6, nil, "um" },
  [1219745] = { "Infondi in modo permanente nei tuoi spallacci la Soul of the Bloodseeker:\n\nI colpi critici di Dominazione riportano al massimo la durata di Squartamento sul tuo bersaglio.", nil, 0xebd4fcb3, nil, "um" },
  [1219747] = { "Infondi in modo permanente nei tuoi spallacci l'Anima del ⟦Titan=Titano⟧:\n\nLe tue abilità Assalto Eroico, Contusione e Dominazione infliggono il $N1% di danni in più.", nil, 0x4bb8bcc4, nil, "um" },
  [1219748] = { "Infondi in modo permanente nei tuoi spallacci la Soul of the Destroyer:\n\nI tuoi colpi di Contusione azzerano il tempo di recupero residuo delle abilità Assalto Mortale, Sete di Sangue e Colpo di Scudo.", nil, 0xb3511461, nil, "um" },
  [1219749] = { "Infondi in modo permanente nei tuoi spallacci la Soul of the Deathbound:\n\nRiduce del $N1% il tempo di recupero del tuo Desiderio di Morte.", nil, 0x6d33caab, nil, "um" },
  [1219751] = { "Infondi in modo permanente nei tuoi spallacci la Soul of the Sanguinist:\n\nInfliggi il $N1% di danni in più mentre un qualsiasi nemico vicino è afflitto sia dal tuo Squartamento sia dalle tue Ferite Profonde.", nil, 0xec347a3b, nil, "um" },
  [1219752] = { "Infondi in modo permanente nei tuoi spallacci la Soul of the Pristine Blocker:\n\nAumenta l'indice di blocco con lo scudo di $N1.", nil, 0xa3fc2dbf, nil, "um" },
  [1219753] = { "Infondi in modo permanente nei tuoi spallacci la Soul of the Savage:\n\nOttieni $N1 rabbia aggiuntiva ogni volta che subisci danni o infliggi danni con l'attacco automatico.", nil, 0x812cea45, nil, "um" },
  [1219754] = { "Infondi in modo permanente nei tuoi spallacci la Soul of Enmity:\n\nAumenta di un ulteriore $N1% tutta la minaccia che generi in Postura da Difesa e del $N2% tutti i danni che infliggi in Gladiator Stance.", nil, 0x2e92bf79, nil, "um" },
  [1219755] = { "Infondi in modo permanente nei tuoi spallacci la Soul of the Deflective:\n\nOttieni $N1 rabbia ogni volta che pari o che uno dei tuoi attacchi viene parato.", nil, 0x7661e34f, nil, "um" },
  [1219756] = { "Infondi in modo permanente nei tuoi spallacci la Soul of the Revenger:\n\nRivincita ti conferisce anche Raffica di Colpi, che aumenta la tua velocità d'attacco del $N1% per i prossimi $N2 colpi.", nil, 0xcbcbce57, nil, "um" },
  [1219757] = { "Infondi in modo permanente nei tuoi spallacci la Soul of the Incessant:\n\nQuando il tuo bersaglio para un attacco, esegui istantaneamente una Reazione contro di lui che infligge il $N1% dei danni dell'arma. Reazione non può essere schivata, bloccata o parata, ma può verificarsi solo una volta ogni $D1 per bersaglio.", nil, 0xf0ea1ade, nil, "um" },
  [1219758] = { "Infondi in modo permanente nei tuoi spallacci la Soul of the Thunderbringer:\n\nRiduce del $N1% il tempo di recupero di Schianto del Tuono.", nil, 0xe475b182, nil, "um" },
  [1219760] = { "Infondi in modo permanente nei tuoi spallacci la Soul of the Sentinel:\n\nIl tuo Colpo di Scudo genera il $N1% di minaccia in più e il suo tempo di recupero si azzera se viene schivato, parato o bloccato.", nil, 0xa46ccaa4, nil, "um" },
  [1219762] = { "Infondi in modo permanente nei tuoi spallacci la Soul of the Southpaw:\n\nRiduce il tempo di recupero di Colpo di Scudo di $D1.", nil, 0xcb63e17e, nil, "um" },
  [1219763] = { "Infondi in modo permanente nei tuoi spallacci la Soul of the Gladiator:\n\nRiduce il tempo di recupero di Rabbia del Sangue di $D1 mentre sei in Gladiator Stance.", nil, 0xcf05ad3a, nil, "um" },
  [1219764] = { "Infondi in modo permanente nei tuoi spallacci la Soul of the Aftershock:\n\nRiduce del $N1% il tempo di recupero di Onda d'Urto.", nil, 0xb1f318bc, nil, "um" },
  [1219766] = { "Infondi in modo permanente nei tuoi spallacci la Soul of the Avoidant:\n\nFinta conferisce anche Elusione per $D1, riducendo del $N2% tutti i danni subiti dagli attacchi ad area dei non giocatori.", nil, 0xf0f83cd1, nil, "um" },
  [1219767] = { "Infondi in modo permanente nei tuoi spallacci la Soul of the Toxicologist:\n\nAumenta del $N1% il bonus ai danni critici dei tuoi veleni.", nil, 0xc7d102e7, nil, "um" },
  [1219768] = { "Infondi in modo permanente nei tuoi spallacci la Soul of the Executioner:\n\nLe tue mosse risolutive hanno una probabilità del $N1% per punto combo di azzerare il costo in energia della tua prossima abilità.", nil, 0x823e6a92, nil, "um" },
  [1219769] = { "Infondi in modo permanente nei tuoi spallacci la Soul of the Opportunist:\n\nLe tue mosse d'apertura hanno una probabilità del $N1% di azzerare il costo in energia della tua prossima abilità.", nil, 0x35a70f81, nil, "um" },
  [1219770] = { "Infondi in modo permanente nei tuoi spallacci la Soul of the Butcher:\n\nAumenta del $N1% i danni inflitti dall'arma nella mano primaria con le abilità che generano punti combo.", nil, 0x76d9111b, nil, "um" },
  [1219771] = { "Infondi in modo permanente nei tuoi spallacci la Soul of the Phantom:\n\nRiduce il tempo di recupero di Sparizione a $D1. Non cumulabile con Elusività.", nil, 0x1bc330fb, nil, "um" },
  [1219772] = { "Infondi in modo permanente nei tuoi spallacci la Soul of the Scoundrel:\n\nAumenta del $N1% i danni di Mutilazione e Fendente di Sciabola.", nil, 0x2dfcb1fc, nil, "um" },
  [1219773] = { "Infondi in modo permanente nei tuoi spallacci la Soul of the Thrill Seeker:\n\nRiduce il tempo di recupero di Scarica d'Adrenalina di $D1.", nil, 0xfe108859, nil, "um" },
  [1219774] = { "Infondi in modo permanente nei tuoi spallacci la Soul of the Shiv Savant:\n\nAumenta del $N1% la tua probabilità di infliggere un colpo critico con i pugnali.", nil, 0x0cfc4bb0, nil, "um" },
  [1219775] = { "Infondi in modo permanente nei tuoi spallacci la Soul of the Stalker:\n\nAumenta la probabilità di critico di Imboscata del $N1%.", nil, 0xf5740008, nil, "um" },
  [1219776] = { "Infondi in modo permanente nei tuoi spallacci la Soul of the Efficient:\n\nLe tue mosse risolutive costano il $N1% di energia in meno.", nil, 0xd6d7a76d, nil, "um" },
  [1219777] = { "Infondi in modo permanente nei tuoi spallacci la Soul of the Knife Juggler:\n\nMentre Just a Flesh Wound e Lame Danzanti sono attivi, Tempesta Cremisi, Schioppo e Ventaglio di Lame costano $N1 energia in meno e generano il $N2% di minaccia in più.", nil, 0xc8a196c6, nil, "um" },
  [1219778] = { "Infondi in modo permanente nei tuoi spallacci la Soul of the Shadow Master:\n\nSparizione ora riduce del $N1% tutti i danni magici che subisci per tutta la sua durata, ma non conferisce più Furtività e non rimuove più gli effetti che riducono il movimento.", nil, 0x7bbdfaa6, nil, "um" },
  [1219779] = { "Infondi in modo permanente nei tuoi spallacci la Soul of the Equilibrist:\n\nLe tue mosse risolutive hanno una probabilità del $N1% per punto combo di farti subire il $N2% di danni fisici in meno dal prossimo attacco in mischia che ti colpisce entro $D1.", nil, 0x27c916bc, nil, "um" },
  [1219780] = { "Infondi in modo permanente nei tuoi spallacci la Soul of the Poised Brawler:\n\nIl tuo Rolling with the Punches ora si attiva anche ogni volta che ottieni un punto combo.", nil, 0xf3489f80, nil, "um" },
  [1219781] = { "Infondi in modo permanente nei tuoi spallacci la Soul of the Black Belt:\n\nIl tuo Rolling with the Punches ti conferisce anche il $N1% di Armatura in più dagli oggetti per accumulo (fino a un massimo del $N2%).", nil, 0xeebbb56a, nil, "um" },
  [1219782] = { "Infondi in modo permanente nei tuoi spallacci la Soul of the Fencer:\n\nIl tempo di recupero del tuo Doppio Attacco si azzera ogni volta che il tuo bersaglio schiva o para.", nil, 0x1f52ac50, nil, "um" },
  [1219783] = { "Infondi in modo permanente nei tuoi spallacci la Soul of the Swashbuckler:\n\nIl tuo Doppio Attacco ora colpisce $N1 bersaglio vicino aggiuntivo e fa sì che anche il tuo Assalto Funesto colpisca $N2 bersaglio vicino aggiuntivo per $D1. Questi colpi aggiuntivi non vengono duplicati da Vortice di Lame.", nil, 0xd2a43825, nil, "um" },
  [1219784] = { "Infondi in modo permanente nei tuoi spallacci la Soul of the Bloodthirsty:\n\nMentre è attivo, il tuo Doppio Attacco ti cura anche del $N1% di tutti i danni inflitti da Assalto Funesto. Le cure in eccesso diventano una Barriera di Sangue che assorbe danni fino al $N2% della tua salute massima.", nil, 0xa08528c4, nil, "um" },
  [1219785] = { "Infondi in modo permanente nei tuoi spallacci la Soul of the Transfusionist:\n\nLifetap genera il $N1% di mana in più e il $N2% di minaccia in meno.", nil, 0xb75592a0, nil, "um" },
  [1219786] = { "Infondi in modo permanente nei tuoi spallacci la Soul of the Refined:\n\nAumenta del $N1% la tua probabilità di critico con incantesimi e attacchi.", nil, 0xf3d860bd, nil, "um" },
  [1219787] = { "Infondi in modo permanente nei tuoi spallacci la Soul of the Decimator:\n\nLa probabilità di attivazione del tuo talento Notte Fonda aumenta del $N1%. Il tuo Incenerimento ha una probabilità del $N2% di attivare Decimazione indipendentemente dalla salute del bersaglio.", nil, 0xe76090f6, nil, "um" },
  [1219788] = { "Infondi in modo permanente nei tuoi spallacci la Soul of the Rotbringer:\n\nAumenta del $N1% i danni dei tuoi incantesimi periodici e della tua vilguardia.", nil, 0xb6e3a0e3, nil, "um" },
  [1219789] = { "Infondi in modo permanente nei tuoi spallacci la Soul of the Malevolent:\n\nI danni periodici dei tuoi incantesimi Ombrofuoco, Afflizione Instabile e Maledizione dell'Agonia e i danni inflitti dalla tua vilguardia hanno una probabilità del $N1% di conferire l'effetto Shadow Trance.", nil, 0x568af6ea, nil, "um" },
  [1219790] = { "Infondi in modo permanente nei tuoi spallacci la Soul of the Shadowmancer:\n\nDardo d'Ombra infligge il $N1% di danni in più per ogni tuo effetto che affligge il bersaglio, fino a un massimo del $N2%.", nil, 0x038c730d, nil, "um" },
  [1219791] = { "Infondi in modo permanente nei tuoi spallacci la Soul of the Chaos Harbinger:\n\nRiduce del $N1% il tempo di recupero del tuo Dardo del Caos e aumenta del $N2% i danni inflitti da Dardo del Caos e Dardo d'Ombra. Inoltre, Dardo del Caos ora può attivare il tuo talento Dardo d'Ombra Migliorato e gli conferisce $N3 cariche aggiuntive (non cumulabile con le cariche aggiuntive di Ombrofuoco).", nil, 0x25cf8583, nil, "um" },
  [1219792] = { "Infondi in modo permanente nei tuoi spallacci la Soul of the Arsonist:\n\nOgni volta che colpisci un bersaglio con Conflagrazione, ottieni il $N1% di danni da fuoco in più per $D1, effetto che si accumula fino a $N3 volte.", nil, 0x5928b7e4, nil, "um" },
  [1219793] = { "Infondi in modo permanente nei tuoi spallacci la Soul of the Infernal Shepherd:\n\nAumenta del $N1% la potenza d'attacco e i danni magici che il tuo famiglio demoniaco ottiene dalle tue caratteristiche.", nil, 0xfcd8b162, nil, "um" },
  [1219794] = { "Infondi in modo permanente nei tuoi spallacci la Soul of the Demonlord:\n\nAumenta del $N1% i benefici del tuo talento Master Demonologist.", nil, 0x6b4b3b96, nil, "um" },
  [1219795] = { "Infondi in modo permanente nei tuoi spallacci la Soul of the Demonic Exorcist:\n\nEsilio ora è istantaneo e puoi lanciarlo su te stesso quando sei un demone. Non puoi esiliarti mentre hai Rigorosità, e farlo ti applica Rigorosità per $D1.", nil, 0x9a62a4ce, nil, "um" },
  [1219796] = { "Infondi in modo permanente nei tuoi spallacci la Soul of the Pained:\n\nOgni volta che subisci danni, tu e il tuo famiglio ottenete mana pari ai danni subiti, fino a un massimo di $N1 mana per evento. Può avvenire solo una volta ogni pochi secondi.", nil, 0x7ae2ea4c, nil, "um" },
  [1219797] = { "Infondi in modo permanente nei tuoi spallacci la Soul of the Flamewraith:\n\nI colpi di Fendente d'Ombra hanno una probabilità del $N1% di conferirti un frammento d'anima, azzerare il tempo di recupero di Fuoco dell'Anima e rendere istantaneo il tuo prossimo Fuoco dell'Anima lanciato entro $D1.", nil, 0x53c21028, nil, "um" },
  [1219798] = { "Infondi in modo permanente nei tuoi spallacci la Soul of the Fleshfeaster:\n\nMentre hai come bersaglio un nemico entro $N1 m, Conversione Vitale ti conferisce mana a spese della salute del bersaglio, ma gli infligge il $N2% di danni in meno. Il mana ottenuto resta invariato.", nil, 0xf254472e, nil, "um" },
  [1219799] = { "Infondi in modo permanente nei tuoi spallacci la Soul of the Abyssal:\n\nMentre Metamorfosi è attiva, le tue abilità offensive e le evocazioni di demoni non costano frammenti d'anima. Inoltre, ti curi del $N1% della tua salute massima quando danneggi un bersaglio con Combustione dell'Ombra.", nil, 0xe893887a, nil, "um" },
  [1219800] = { "Infondi in modo permanente nei tuoi spallacci la Soul of the Voidborne:\n\nLe cure in eccesso che ricevi da te stesso vengono convertite in uno scudo che assorbe i danni. Questo scudo può assorbire fino al $N1% della tua salute massima e si accumula con più cure.", nil, 0x7a2839db, nil, "um" },
  [1219801] = { "Infondi in modo permanente nei tuoi spallacci la Soul of the Umbral Blade:\n\nRiduce il tempo di recupero del tuo Fendente d'Ombra di $D1.", nil, 0x0d8c8bef, nil, "um" },
  [1219802] = { "Infondi in modo permanente nei tuoi spallacci la Soul of the Ritualist:\n\nGli effetti del tuo Sacrificio Demoniaco ora persistono mentre hai un famiglio demoniaco attivo, purché tu non evochi di nuovo il famiglio sacrificato. Puoi avere attivo un solo effetto di Sacrificio Demoniaco alla volta.", nil, 0x342a9f55, nil, "um" },
  [1219803] = { "Infondi in modo permanente nei tuoi spallacci la Soul of the Pain Spreader:\n\nPer $D1 dopo aver usato Fendente d'Ombra, il tuo Dolore Ustionante colpisce $N2 bersaglio aggiuntivo entro la portata da mischia.", nil, 0x8c03a8b1, nil, "um" },
  [1219804] = { "Infondi in modo permanente nei tuoi spallacci la Soul of the Misleader:\n\nGeneri il $N1% di minaccia in più per $D1 dopo aver usato Tiro Distraente.", nil, 0x90d1ee81, nil, "um" },
  [1219805] = { "Infondi in modo permanente nei tuoi spallacci la Soul of the Preyseeker:\n\nMentre segui le tracce di un tipo di creatura, infliggi il $N1% di danni in più a quel tipo di creatura.", nil, 0x3a0917db, nil, "um" },
  [1219806] = { "Infondi in modo permanente nei tuoi spallacci la Soul of the Sharpshooter:\n\nLa tua prossima abilità di tiro usata entro $D1 dopo Tiro Mirato infligge il $N2% di danni in più.", nil, 0xe4f43428, nil, "um" },
  [1219807] = { "Infondi in modo permanente nei tuoi spallacci la Soul of the Hazard Harrier:\n\nIl tuo Tiro Mirato infligge il $N1% di danni in più ai bersagli colpiti da uno degli effetti delle tue trappole.", nil, 0x773fa0d0, nil, "um" },
  [1219808] = { "Infondi in modo permanente nei tuoi spallacci la Soul of the Alternator:\n\nLe tue abilità di tiro offensive infliggono il $N1% di danni in più se il tiro offensivo precedente era diverso da quello attuale.", nil, 0x4b7438ab, nil, "um" },
  [1219809] = { "Infondi in modo permanente nei tuoi spallacci la Soul of the Toxinologist:\n\nI danni del tuo Morso del Serpente aumentano del $N1% della tua potenza d'attacco nell'arco della sua durata normale.", nil, 0xa58e22df, nil, "um" },
  [1219810] = { "Infondi in modo permanente nei tuoi spallacci la Soul of the Bounty Hunter:\n\nAumenta del $N1% i danni di Tiro Mortale contro i bersagli non controllati da giocatori.", nil, 0xda55dbbd, nil, "um" },
  [1219811] = { "Infondi in modo permanente nei tuoi spallacci la Soul of the Trick Shooter:\n\nIl tempo di recupero di Tiro Mortale è ridotto del $N1%. Mentre Rapidità di Tiro è attiva con Uccisione Rapida incisa, Tiro Mortale non ha tempo di recupero e, quando viene usato contro un bersaglio non controllato da giocatori, scaglia $N2 Tiri Mortali aggiuntivi al $N3% dei danni, con una portata minima.", nil, 0x3d746cf2, nil, "um" },
  [1219812] = { "Infondi in modo permanente nei tuoi spallacci la Soul of the Beast Tender:\n\nAumenta del $N1% la potenza d'attacco che il tuo famiglio bestia ottiene dalle tue caratteristiche.", nil, 0xa266e059, nil, "um" },
  [1219813] = { "Infondi in modo permanente nei tuoi spallacci la Soul of the Hound Master:\n\nAumenta del $N1% la rigenerazione di Focus del tuo famiglio bestia.", nil, 0xbbc6f103, nil, "um" },
  [1219815] = { "Infondi in modo permanente nei tuoi spallacci la Soul of the Alpha Tamer:\n\nAumenta del $N1% la rigenerazione di Focus dei tuoi famigli.", nil, 0xe02c301c, nil, "um" },
  [1219816] = { "Infondi in modo permanente nei tuoi spallacci la Soul of the Huntsman:\n\nMorso della Mangusta riduce anche del $N1% la probabilità di schivata del bersaglio e aumenta del $N2% la tua probabilità d'impatto per $D1.", nil, 0xb06629f3, nil, "um" },
  [1219818] = { "Infondi in modo permanente nei tuoi spallacci la Soul of the Retaliator:\n\nMorso della Mangusta si attiva anche per $D1 ogni volta che il bersaglio para o blocca o quando il tuo attacco in mischia va a vuoto.", nil, 0x4c1c911d, nil, "um" },
  [1219819] = { "Infondi in modo permanente nei tuoi spallacci la Soul of Echoes:\n\nAssalto del Raptor aumenta del $N2% i danni inflitti dalla tua prossima altra abilità in mischia (escluso Laccio) entro $D1.", nil, 0xb36bf6ba, nil, "um" },
  [1219820] = { "Infondi in modo permanente nei tuoi spallacci la Soul of the Lethal Lasher:\n\nAumenta del $N1% i danni inflitti dall'arma nella mano primaria con Assalto del Raptor e Wyvern Strike.", nil, 0x32c0d640, nil, "um" },
  [1219821] = { "Infondi in modo permanente nei tuoi spallacci la Soul of the Kineticist:\n\nI tuoi danni periodici hanno il $N1% di probabilità di azzerare il tempo di recupero di una delle tue abilità di assalto. Viene sempre scelto l'assalto con il tempo di recupero residuo più lungo.", nil, 0x7f1ab835, nil, "um" },
  [1219822] = { "Infondi in modo permanente nei tuoi spallacci la Soul of the Strategist:\n\nAumenta del $N1% i danni periodici di Wyvern Strike e di $N2 il Focus massimo del tuo famiglio.", nil, 0x168d3e9c, nil, "um" },
  [1219823] = { "Infondi in modo permanente nei tuoi spallacci la Soul of the Deadly Striker:\n\nAumenta del $N1% i danni dell'impatto di Morso della Mangusta e di tutte le abilità di assalto.", nil, 0xd5fad7da, nil, "um" },
  [1219824] = { "Infondi in modo permanente nei tuoi spallacci la Soul of the Hastened Healer:\n\n-$D1 al tempo di lancio di Cura Rapida e -$D2 al tempo di lancio di Cura Maggiore.", nil, 0x9ab400ed, nil, "um" },
  [1219825] = { "Infondi in modo permanente nei tuoi spallacci la Soul of the Refined:\n\nAumenta del $N1% la tua probabilità di critico con incantesimi e attacchi.", nil, 0xf3b6131f, nil, "um" },
  [1219826] = { "Infondi in modo permanente nei tuoi spallacci la Soul of the Celebrant:\n\nAumenta del $N1% la tua probabilità di critico con Preghiera di Cura e Circolo di Guarigione.", nil, 0x710f3501, nil, "um" },
  [1219827] = { "Infondi in modo permanente nei tuoi spallacci la Soul of the Faithful:\n\nPermette al $N1% della rigenerazione del mana di continuare durante il lancio di incantesimi.", nil, 0x0830d48d, nil, "um" },
  [1219828] = { "Infondi in modo permanente nei tuoi spallacci la Soul of the Serendipitous:\n\nLe tue cure periodiche hanno una probabilità del $N1% di rendere istantaneo il tuo prossimo incantesimo con un tempo di lancio inferiore a $N2 s.", nil, 0x24bd33e1, nil, "um" },
  [1219829] = { "Infondi in modo permanente nei tuoi spallacci la Soul of the Resonant:\n\nCircolo di Guarigione e Contrizione applicano anche ai loro bersagli un effetto di cura periodica che cura del $N1% di tale quantità in $D1.", nil, 0xb78e45a1, nil, "um" },
  [1219830] = { "Infondi in modo permanente nei tuoi spallacci la Soul of the Devotee:\n\nLa tua Preghiera di Guarigione ottiene $N1 cariche aggiuntive.", nil, 0xe02e70d2, nil, "um" },
  [1219831] = { "Infondi in modo permanente nei tuoi spallacci la Soul of the Archbishop:\n\nIl tuo Circolo di Guarigione ora cura il membro più ferito del gruppo bersaglio del $N1% in più.", nil, 0x6a8a1a27, nil, "um" },
  [1219832] = { "Infondi in modo permanente nei tuoi spallacci la Soul of the Penitent:\n\nRiduce il tempo di recupero di Contrizione di $D1.", nil, 0x9d26bb1c, nil, "um" },
  [1219833] = { "Infondi in modo permanente nei tuoi spallacci la Soul of the Soul Warder:\n\nAumenta del $N1% i danni assorbiti dal tuo incantesimo Parola del Potere: Scudo.", nil, 0xcd0b1c0f, nil, "um" },
  [1219834] = { "Infondi in modo permanente nei tuoi spallacci la Soul of the Twilight Walker:\n\nPuoi lanciare Cura Rapida in Forma d'Ombra.", nil, 0xddccd53e, nil, "um" },
  [1219835] = { "Infondi in modo permanente nei tuoi spallacci la Soul of the Mind Breaker:\n\nI colpi critici di Detonazione Mentale riducono del $N1% la durata del tuo prossimo Flagello Mentale, aumentandone del $N2% i danni totali.", nil, 0xd3ce0447, nil, "um" },
  [1219836] = { "Infondi in modo permanente nei tuoi spallacci la Soul of the Deathdealer:\n\nRiduce il tempo di recupero di Parola d'Ombra: Morte di $D1.", nil, 0x85a70d75, nil, "um" },
  [1219837] = { "Infondi in modo permanente nei tuoi spallacci la Soul of the Spirit Font:\n\nLa tua Parola d'Ombra: Dolore ha una probabilità del $N1% per punto talento in Spirit Tap di attivare il tuo talento Spirit Tap quando infligge danni, o del $N2% per punto talento quando un bersaglio muore con la tua Parola d'Ombra: Dolore attiva. Anche Concentrazione Interiore ha una probabilità del $N3% per punto talento di attivare Spirit Tap.", nil, 0xc60a4683, nil, "um" },
  [1219838] = { "Infondi in modo permanente nei tuoi spallacci la Soul of the Zealot:\n\nMentre Spirit Tap è attivo, infliggi il $N1% di danni da ombra in più.", nil, 0x67a3a9a3, nil, "um" },
  [1219839] = { "Infondi in modo permanente nei tuoi spallacci la Soul of the Unwavering Defiler:\n\nIl tuo Flagello Mentale non perde più durata quando subisci danni e, al lancio, scaglia sul bersaglio un Aculeo Mentale gratuito.", nil, 0xd3d17c8f, nil, "um" },
  [1219840] = { "Infondi in modo permanente nei tuoi spallacci la Soul of the Contemnor:\n\nIl tuo Aculeo Mentale ora è istantaneo, infligge il $N1% di danni in più e può essere lanciato mentre canalizzi un altro incantesimo.", nil, 0xf37bd08a, nil, "um" },
  [1219841] = { "Infondi in modo permanente nei tuoi spallacci la Soul of the Plaguebringer:\n\nLa tua runa Dolore e Sofferenza ora può rinnovare la durata di Piaga Divoratrice.", nil, 0x05886fbb, nil, "um" },
  [1219842] = { "Infondi in modo permanente nei tuoi spallacci la Soul of the Reverberant:\n\nI tuoi Temporal Beacon durano il $N1% in più.", nil, 0x309939fb, nil, "um" },
  [1219843] = { "Infondi in modo permanente nei tuoi spallacci la Soul of the Chronohealer:\n\nAumenta del $N1% tutte le cure cronomantiche che effettui.", nil, 0x38053f49, nil, "um" },
  [1219844] = { "Infondi in modo permanente nei tuoi spallacci la Soul of Temporal Longing:\n\nOgni volta che curi un bersaglio con Rigenerazione, il tempo di recupero rimanente di Riavvolgimento Temporale si riduce di $D1.", nil, 0xb93c079f, nil, "um" },
  [1219845] = { "Infondi in modo permanente nei tuoi spallacci la Soul of the Precognitive:\n\nI tuoi Missili Arcani restituiscono il $N1% del loro costo base in mana ogni volta che infliggono danni.", nil, 0xed6e9d75, nil, "um" },
  [1219846] = { "Infondi in modo permanente nei tuoi spallacci la Soul of the Arcanist:\n\nDetonazione Arcana ottiene una probabilità aggiuntiva del $N1% di attivare Raffica di Missili, e Raffica di Missili ora influisce su Rigenerazione come su Missili Arcani.", nil, 0xed8c7d34, nil, "um" },
  [1219847] = { "Infondi in modo permanente nei tuoi spallacci la Soul of the Eternal Caretaker:\n\nI tuoi Temporal Beacon applicati da Rigenerazione di Massa ora durano $D1.", nil, 0x93607967, nil, "um" },
  [1219848] = { "Infondi in modo permanente nei tuoi spallacci la Soul of the Spellbider:\n\nLa tua Detonazione Arcana aumenta i danni inflitti di un ulteriore $N1% per accumulo.", nil, 0x84091821, nil, "um" },
  [1219849] = { "Infondi in modo permanente nei tuoi spallacci la Soul of the Wardshaper:\n\nScudo di Mana, Guardia di Fuoco e Protezione dal Gelo assorbono il $N1% di danni in più e applicano anche Temporal Beacon al bersaglio per $D1.", nil, 0xf08d0200, nil, "um" },
  [1219850] = { "Infondi in modo permanente nei tuoi spallacci la Soul of Winter's Grasp:\n\nAumenta di un ulteriore $N1% la probabilità di attivare la tua runa Dita di Gelo.", nil, 0x4ea4cb97, nil, "um" },
  [1219851] = { "Infondi in modo permanente nei tuoi spallacci la Soul of the Cryomancer:\n\nAumenta del $N1% i danni inflitti dai tuoi incantesimi Dardo di Gelo e Dardo di Geloincanto.", nil, 0xa97bced4, nil, "um" },
  [1219852] = { "Infondi in modo permanente nei tuoi spallacci la Soul of the Evoker:\n\nSei immune a tutti i danni mentre canalizzi Evocazione.", nil, 0xb8a6b955, nil, "um" },
  [1219853] = { "Infondi in modo permanente nei tuoi spallacci la Soul of the Elementalist:\n\nOttieni il $N1% di danni in più per $D1 ogni volta che lanci un incantesimo di una scuola di magia diversa.", nil, 0x5ab56f0c, nil, "um" },
  [1219854] = { "Infondi in modo permanente nei tuoi spallacci la Soul of the Magical Armorer:\n\nArmatura Magica aumenta di un ulteriore $N1% la tua rigenerazione del mana durante il lancio. Armatura Lavica aumenta di $N2 i tuoi danni magici e le tue cure. Armatura di Ghiaccio aumenta del $N3% la probabilità di attivare Dita di Gelo.", nil, 0xd484e42d, nil, "um" },
  [1219855] = { "Infondi in modo permanente nei tuoi spallacci la Soul of the Kindler:\n\nRiduce del $N1% la minaccia generata dai tuoi incantesimi di fuoco.", nil, 0xc429d5b8, nil, "um" },
  [1219856] = { "Infondi in modo permanente nei tuoi spallacci la Soul of Fiery Convergence:\n\nLa tua Pirosfera infligge il $N1% di danni in più ai bersagli colpiti dall'effetto periodico della tua Palla di Fuoco.", nil, 0x42ed8f92, nil, "um" },
  [1219857] = { "Infondi in modo permanente nei tuoi spallacci la Soul of the Perpetual Blaze:\n\nL'effetto periodico della tua Palla di Fuoco infligge danni aggiuntivi nell'arco della sua durata pari al $N1% dei danni dell'impatto.", nil, 0xbb4a5dbb, nil, "um" },
  [1219858] = { "Infondi in modo permanente nei tuoi spallacci la Soul of the Pyromaniac:\n\nLa tua Detonazione di Fuoco ora aumenta anche del $N1% la probabilità di critico del tuo prossimo incantesimo di fuoco per $D1.", nil, 0x7087ef35, nil, "um" },
  [1219859] = { "Infondi in modo permanente nei tuoi spallacci la Soul of the Igniter:\n\nAumenta del $N1% i danni inflitti dal tuo talento Incendio.", nil, 0x00814fae, nil, "um" },
  [1219860] = { "Infondi in modo permanente nei tuoi spallacci la Soul of the Torcher:\n\nI tuoi incantesimi Palla di Fuoco, Palla di Fuocogelo e Balefire Bolt infliggono il $N1% di danni in più per ognuno dei tuoi effetti di fuoco sul bersaglio, fino a un massimo del $N2%.", nil, 0x8eec4150, nil, "um" },
  [1219861] = { "Infondi in modo permanente nei tuoi spallacci la Soul of the Pristine Blocker:\n\nAumenta l'indice di blocco con lo scudo di $N1.", nil, 0xa3d99c99, nil, "um" },
  [1219862] = { "Infondi in modo permanente nei tuoi spallacci la Soul of the Lightwarden:\n\nTi curi di $N1 quando blocchi. La cura può avvenire solo una volta ogni pochi secondi.", nil, 0x76f4d5d7, nil, "um" },
  [1219863] = { "Infondi in modo permanente nei tuoi spallacci la Soul of the Radiant Defender:\n\nScudo Benedetto non ha più cariche e dura sempre per tutta la sua durata. Inoltre, i suoi danni aumentano del $N1% del tuo indice di blocco con lo scudo.", nil, 0x7eefa41c, nil, "um" },
  [1219864] = { "Infondi in modo permanente nei tuoi spallacci la Soul of the Shieldbearer:\n\nAumenta del $N1% la probabilità di blocco aggiuntiva conferita da Scudo Benedetto.", nil, 0x9d8d9669, nil, "um" },
  [1219865] = { "Infondi in modo permanente nei tuoi spallacci la Soul of the Bastion:\n\nSubisci il $N1% di danni in meno mentre Scudo Benedetto è attivo.", nil, 0xe371efdf, nil, "um" },
  [1219866] = { "Infondi in modo permanente nei tuoi spallacci la Soul of the Reckoner:\n\nIl tuo talento Regolamento di Conti ora ha una probabilità del $N1% per punto talento di attivarsi quando blocchi.", nil, 0xf7d85cb2, nil, "um" },
  [1219867] = { "Infondi in modo permanente nei tuoi spallacci la Soul of the Ironclad:\n\nIl tuo Blessing of Sanctuary, se lanciato su te stesso, aumenta anche del $N1% tutte le caratteristiche.", nil, 0xb089c840, nil, "um" },
  [1219868] = { "Infondi in modo permanente nei tuoi spallacci la Soul of the Guardian:\n\nShield of the Righteous rende istantanea la tua prossima Luce Sacra. Se lanciata su te stesso, restituisce il $N1% del suo costo in mana e non è influenzata da Protezione della Luce.", nil, 0x29738ef7, nil, "um" },
  [1219869] = { "Infondi in modo permanente nei tuoi spallacci la Soul of the Peacekeeper:\n\nAumenta al $N1% la probabilità che gli alleati attivino il tuo Judgement of Light o Judgement of Wisdom.", nil, 0x2d7175c3, nil, "um" },
  [1219870] = { "Infondi in modo permanente nei tuoi spallacci la Soul of the Refined:\n\nAumenta del $N1% la tua probabilità di critico con incantesimi e attacchi.", nil, 0xf3d7d99f, nil, "um" },
  [1219871] = { "Infondi in modo permanente nei tuoi spallacci la Soul of the Exemplar:\n\nOgni volta che Lampo di Luce, Luce Sacra o Faro di Luce curano un bersaglio fino alla salute piena, curi anche tutti i membri del suo gruppo di $N1 salute.", nil, 0x31595f8b, nil, "um" },
  [1219872] = { "Infondi in modo permanente nei tuoi spallacci la Soul of the Inquisitor:\n\nAumenta del $N1% la probabilità di critico di Folgore Sacra.", nil, 0xf8fc7d11, nil, "um" },
  [1219873] = { "Infondi in modo permanente nei tuoi spallacci la Soul of the Sovereign:\n\nAumenta del $N1% i danni inflitti dalla tua Consacrazione.", nil, 0xe578c6c3, nil, "um" },
  [1219874] = { "Infondi in modo permanente nei tuoi spallacci la Soul of the Dominus:\n\nQuando non sei tu il bersaglio del tuo Faro di Luce, anche il bersaglio del tuo Faro di Luce viene curato del $N1% dei danni che infliggi con Consacrazione, Esorcismo, Folgore Sacra, Ira Sacra e Martello dell'Ira.", nil, 0x4253c983, nil, "um" },
  [1219875] = { "Infondi in modo permanente nei tuoi spallacci la Soul of the Vindicator:\n\nRiduce del $N1% il tempo di recupero di Luce Divina.", nil, 0x0a2aa45f, nil, "um" },
  [1219876] = { "Infondi in modo permanente nei tuoi spallacci la Soul of the Altruist:\n\nLe tue cure sul bersaglio del tuo Faro di Luce curano anche il bersaglio amico ferito più vicino del $N1% di tale quantità.", nil, 0x68861e5c, nil, "um" },
  [1219877] = { "Infondi in modo permanente nei tuoi spallacci la Soul of the Arbiter:\n\nI tuoi Judgement of Light e Judgement of Wisdom conferiscono anche gli effetti di Giudizio del Crociato.", nil, 0x9db1e989, nil, "um" },
  [1219878] = { "Infondi in modo permanente nei tuoi spallacci la Soul of the Sealbearer:\n\nSigillo del Comando, Sigillo della Rettitudine, Seal of Martyrdom e Luce Solare infliggono il $N1% di danni in meno, ma ora persistono per $N2 s dopo che hai lanciato un altro sigillo, o finché non ne lanci un terzo. I tuoi Giudizi ora possono attivare più sigilli, se sono attivi.", nil, 0x66204e45, nil, "um" },
  [1219879] = { "Infondi in modo permanente nei tuoi spallacci la Soul of the Justicar:\n\nAumenta del $N1% i danni inflitti dai tuoi Giudizi offensivi e i tuoi Giudizi non consumano più i Sigilli sul bersaglio. I tuoi Giudizi ora possono attivare più Sigilli, se attivi.", nil, 0xfab12449, nil, "um" },
  [1219880] = { "Infondi in modo permanente nei tuoi spallacci la Soul of the Judicator:\n\nRiduce il tempo di recupero di Giudizio di $D1, ma riduce del $N2% i danni inflitti dai tuoi Giudizi.", nil, 0x4e512e5b, nil, "um" },
  [1219881] = { "Infondi in modo permanente nei tuoi spallacci la Soul of the Ascendant:\n\nIl tuo Giudizio aumenta i danni da sacro del $N1% per $D1, effetto che si accumula fino a $N3 volte.", nil, 0xf0c82a56, nil, "um" },
  [1219882] = { "Infondi in modo permanente nei tuoi spallacci la Soul of the Retributor:\n\nAumenta del $N1% i danni di Assalto del Crociato.", nil, 0x1b794919, nil, "um" },
  [1219883] = { "Infondi in modo permanente nei tuoi spallacci la Soul of the Excommunicator:\n\nI tuoi attacchi base con armi da mischia a due mani aumentano i danni del tuo prossimo Esorcismo lanciato entro $D1 del $N2%. Si accumula fino a $N3 volte.", nil, 0x3feea6a8, nil, "um" },
  [1219884] = { "Infondi in modo permanente nei tuoi spallacci la Soul of the Lightbringer:\n\nAumenta del $N1% i danni inflitti dal tuo incantesimo Folgore Sacra.", nil, 0x9dac3aaf, nil, "um" },
  [1219885] = { "Infondi in modo permanente nei tuoi spallacci la Soul of the Exile:\n\nRiduce il tempo di recupero di Esorcismo di $D1 e ne aumenta i danni inflitti del $N2%.", nil, 0x49e77c8f, nil, "um" },
  [1219886] = { "Infondi in modo permanente nei tuoi spallacci la Soul of the Templar:\n\nCon un'arma a una mano equipaggiata, Assalto del Crociato ora scatena l'effetto di Giudizio dei tuoi sigilli, ma non consuma il sigillo.", nil, 0xbf03dfa5, nil, "um" },
  [1219887] = { "Infondi in modo permanente nei tuoi spallacci la Soul of the Windwalker:\n\nAumenta del $N1% la tua velocità d'attacco per i tuoi prossimi $N2 colpi dopo aver parato, schivato o bloccato.", nil, 0xae1e61ed, nil, "um" },
  [1219888] = { "Infondi in modo permanente nei tuoi spallacci la Soul of the Shield Master:\n\nLe tue parate e schivate attivano anche l'abilità della runa Maestria nello Scudo.", nil, 0x0504a004, nil, "um" },
  [1219889] = { "Infondi in modo permanente nei tuoi spallacci la Soul of the Totemic Protector:\n\nIl tuo Totem della Pelle di Pietra riduce anche del $N1% i danni fisici subiti e il tuo Windwall Totem riduce anche del $N2% i danni magici subiti.", nil, 0x0b18bf10, nil, "um" },
  [1219890] = { "Infondi in modo permanente nei tuoi spallacci la Soul of the Shock-Absorber:\n\nLa tua Folgore del Fuoco aumenta anche del $N1% la probabilità di blocco per $D1 o finché non blocchi un attacco.", nil, 0xac5cd6ca, nil, "um" },
  [1219891] = { "Infondi in modo permanente nei tuoi spallacci la Soul of the Spiritual Bulwark:\n\nOgni volta che blocchi, il valore di blocco aumenta del $N1% dei tuoi danni magici per $D1, effetto che si accumula fino a $N3 volte.", nil, 0xc2b0eddc, nil, "um" },
  [1219892] = { "Infondi in modo permanente nei tuoi spallacci la Soul of the Maelstrombringer:\n\nOgni volta che blocchi un attacco, hai una probabilità del $N1% di attivare la tua runa Arma del Maelstrom.", nil, 0x98ad705b, nil, "um" },
  [1219893] = { "Infondi in modo permanente nei tuoi spallacci la Soul of the Lavawalker:\n\nInfliggere danni a un bersaglio con Assalto della Tempesta, Getto di Lava o Detonazione Fusa riduce anche del $N1% tutti i danni che subisci per $D1.", nil, 0xfa020d01, nil, "um" },
  [1219894] = { "Infondi in modo permanente nei tuoi spallacci la Soul of the True Alpha:\n\nQuando lanci Spirit of the Alpha su te stesso, aumenta anche del $N1% la tua salute, del $N2% la minaccia che generi e del $N3% tutti i danni che infliggi.", nil, 0x598d83ec, nil, "um" },
  [1219895] = { "Infondi in modo permanente nei tuoi spallacci la Soul of the Totemkeeper:\n\nIl raggio dei tuoi totem che hanno effetto sui bersagli amici aumenta a $N1 m.", nil, 0x26b268a9, nil, "um" },
  [1219896] = { "Infondi in modo permanente nei tuoi spallacci la Soul of the Ancestors:\n\nDopo aver lanciato Ondata di Cura, Ondata di Cura Inferiore o Marea Gelida, hai una probabilità del $N1% di ottenere mana pari al $N2% del costo base dell'incantesimo.", nil, 0x18780f59, nil, "um" },
  [1219897] = { "Infondi in modo permanente nei tuoi spallacci la Soul of the Spiritweaver:\n\nLa tua Ondata di Cura ora rimbalza su altri bersagli vicini. Ogni rimbalzo riduce del $N1% l'efficacia della cura, e l'incantesimo rimbalza su un massimo di $N2 bersagli aggiuntivi.", nil, 0xcc0088f5, nil, "um" },
  [1219898] = { "Infondi in modo permanente nei tuoi spallacci la Soul of the Waterwalker:\n\nI tuoi colpi critici non periodici di danno e di cura ora hanno una probabilità del $N1% di attivare il tuo Scudo d'Acqua, senza consumarne una carica né attivarne il tempo di recupero.", nil, 0x8ff1a2e1, nil, "um" },
  [1219899] = { "Infondi in modo permanente nei tuoi spallacci la Soul of the Stormtender:\n\nLa tua Catena di Fulmini ora cura anche il bersaglio del tuo Scudo di Terra più recente del $N1% dei danni inflitti.", nil, 0xaf285f89, nil, "um" },
  [1219900] = { "Infondi in modo permanente nei tuoi spallacci la Soul of the Elemental Seer:\n\nAumenta del $N1% le cure di Catena di Guarigione e i danni di Catena di Fulmini.", nil, 0x9ad749dc, nil, "um" },
  [1219901] = { "Infondi in modo permanente nei tuoi spallacci la Soul of the Vitalist:\n\nLa tua Marea Gelida aumenta di un ulteriore $N1% la quantità curata da Catena di Guarigione.", nil, 0xac47edcc, nil, "um" },
  [1219902] = { "Infondi in modo permanente nei tuoi spallacci la Soul of the Spirithealer:\n\nRiduce il tempo di lancio di Catena di Guarigione di $D1.", nil, 0x62a088c4, nil, "um" },
  [1219903] = { "Infondi in modo permanente nei tuoi spallacci la Soul of the Refined:\n\nAumenta del $N1% la tua probabilità di critico con incantesimi e attacchi.", nil, 0xf3d86031, nil, "um" },
  [1219904] = { "Infondi in modo permanente nei tuoi spallacci la Soul of the Chieftain:\n\nIl tuo talento Raffica di Colpi aumenta la tua velocità d'attacco di un ulteriore $N1%.", nil, 0x15deb29a, nil, "um" },
  [1219905] = { "Infondi in modo permanente nei tuoi spallacci la Soul of the Furycharged:\n\nLa tua probabilità di attivare Folgore Statica aumenta del $N1% (del $N2% se combatti con due armi).", nil, 0xde6f8cb0, nil, "um" },
  [1219906] = { "Infondi in modo permanente nei tuoi spallacci la Soul of the Stormbreaker:\n\nAumenta del $N1% i danni con la mano primaria inflitti dal tuo Assalto della Tempesta.", nil, 0x5d83820c, nil, "um" },
  [1219907] = { "Infondi in modo permanente nei tuoi spallacci la Soul of the Tempest:\n\nMentre Folgore Statica è incisa, il tuo Scudo di Fulmini ottiene una carica ogni volta che colpisci un bersaglio con Dardo Fulminante o Catena di Fulmini, fino a un massimo di $N1 cariche. Inoltre, mentre Folgore Statica è incisa, il tuo Scudo di Fulmini può infliggere danni critici.", nil, 0xfd19cb21, nil, "um" },
  [1219908] = { "Infondi in modo permanente nei tuoi spallacci la Soul of the Seismic Smasher:\n\nAumenta del $N1% i danni di Assalto della Tempesta e Sferzata Lavica. L'effetto aumenta al $N2% se usi un'arma a due mani.", nil, 0x9f9f5f7a, nil, "um" },
  [1219909] = { "Infondi in modo permanente nei tuoi spallacci la Soul of the Flamebringer:\n\nI colpi critici di Assalto della Tempesta, Sferzata Lavica e Getto di Lava fanno bruciare il bersaglio, infliggendogli in $D1 il $N1% dei danni inflitti.", nil, 0x796df1fb, nil, "um" },
  [1219910] = { "Infondi in modo permanente nei tuoi spallacci la Soul of the Volcano:\n\nI colpi critici del tuo Dardo Fulminante hanno una probabilità del $N1% di azzerare il tempo di recupero di Getto di Lava e Catena di Fulmini e di rendere istantaneo il prossimo Getto di Lava o Catena di Fulmini lanciato entro $D1.", nil, 0xf91d8a8c, nil, "um" },
  [1219911] = { "Infondi in modo permanente nei tuoi spallacci la Soul of the Raging Flame:\n\nGetto di Lava ora riporta anche la durata di Folgore del Fuoco sul tuo bersaglio a $D1.", nil, 0x9c74d4f5, nil, "um" },
  [1219912] = { "Infondi in modo permanente nei tuoi spallacci la Soul of the Elemental Master:\n\nI tuoi colpi critici magici ora hanno una probabilità del $N1% di attivare il tuo talento Focus Elementale.", nil, 0xcd180551, nil, "um" },
  [1219913] = { "Infondi in modo permanente nei tuoi spallacci la Soul of the Tribesman:\n\nLoyal Beta della tua abilità Spirit of the Alpha ora aumenta anche del $N1% i danni da fuoco, da gelo e da natura.", nil, 0x93bc1d68, nil, "um" },
  [1219914] = { "Infondi in modo permanente nei tuoi spallacci la Soul of the Spirit Guide:\n\nMentre Lancio Istintivo è attivo, infliggi il $N1% di danni non fisici in più.", nil, 0xe4e9a6bd, nil, "um" },
  [1219915] = { "Infondi in modo permanente nei tuoi spallacci la Soul of the Elder:\n\nHai una probabilità del $N1% di evitare l'interruzione causata dai danni durante il lancio di Dardo Fulminante, Catena di Fulmini o Getto di Lava, e una probabilità aumentata del $N2% di attivare il tuo talento Focus Elementale.", nil, 0xe167822e, nil, "um" },
  [1219916] = { "Infondi in modo permanente nei tuoi spallacci la Soul of the Elements:\n\nAumenta del $N1% il bonus ai danni critici dei tuoi incantesimi di fuoco, di gelo e di natura.", nil, 0x4a1d14e2, nil, "um" },
  [1219917] = { "Infondi in modo permanente nei tuoi spallacci la Soul of the Lava Sage:\n\nI danni del tuo Getto di Lava aumentano di una percentuale pari alla tua probabilità di critico magico.", nil, 0xa0d8cb1c, nil, "um" },
  [1219918] = { "Infondi in modo permanente nei tuoi spallacci la Soul of the Ancestral Warden:\n\nAumenta la probabilità di bloccare gli attacchi con lo scudo del $N1%.", nil, 0xa13cc0b8, nil, "um" },
  [1219919] = { "Infondi in modo permanente nei tuoi spallacci la Soul of the Corrupt:\n\nAumenta di un ulteriore $N1% la probabilità di attivare la tua runa Picco Energetico.", nil, 0x0e874516, nil, "um" },
  [1219920] = { "Infondi in modo permanente nei tuoi spallacci la Soul of the Gentle Paw:\n\nPuoi lanciare Pronto Ritorno e Innervazione in Forma d'Orso o in Dire Bear Form.", nil, 0xed2d62bf, nil, "um" },
  [1219921] = { "Infondi in modo permanente nei tuoi spallacci la Soul of the Ferocious:\n\nRiduce di $D1 il tempo di recupero di Rabbia, che non riduce più la tua Armatura.", nil, 0x0db0af0a, nil, "um" },
  [1219922] = { "Infondi in modo permanente nei tuoi spallacci la Soul of the Shifter:\n\nLa Forma d'Orso e la Dire Bear Form aumentano di un ulteriore $N1% tutta la minaccia che generi, e Cower ora elimina tutta la tua minaccia verso il bersaglio, ma il suo tempo di recupero è più lungo di $D1.", nil, 0xb13873a4, nil, "um" },
  [1219923] = { "Infondi in modo permanente nei tuoi spallacci la Soul of the Territorial:\n\nSpazzata fa anche sì che la tua Zampata colpisca $N1 bersaglio aggiuntivo per i prossimi $D1.", nil, 0xc915ac0e, nil, "um" },
  [1219924] = { "Infondi in modo permanente nei tuoi spallacci la Soul of the Beast:\n\nLe tue abilità Mangle (Bear), Spazzata, Zampata e Lacerazione ottengono il $N1% di probabilità di colpo critico in più contro i bersagli colpiti dalla tua Lacerazione.", nil, 0x414187e8, nil, "um" },
  [1219925] = { "Infondi in modo permanente nei tuoi spallacci la Soul of the Lacerator:\n\nLa tua Spazzata ora propaga la tua Lacerazione dal bersaglio principale agli altri bersagli che colpisce.", nil, 0x84e9c305, nil, "um" },
  [1219926] = { "Infondi in modo permanente nei tuoi spallacci la Soul of the Furious:\n\nOgni volta che schivi un attacco in Dire Bear Form, il tuo prossimo Dilaniamento o Spazzata infligge il $N1% di danni in più, effetto cumulabile fino a $N2 volte.", nil, 0x0c368e87, nil, "um" },
  [1219927] = { "Infondi in modo permanente nei tuoi spallacci la Soul of the Mangler:\n\nRiduce di $D1 il tempo di recupero di Mangle (Bear).", nil, 0xf1bb6d4d, nil, "um" },
  [1219928] = { "Infondi in modo permanente nei tuoi spallacci la Soul of the Innervator:\n\nQuando lanci Innervazione su un altro giocatore, viene lanciata anche su di te.", nil, 0xb05b9c8c, nil, "um" },
  [1219929] = { "Infondi in modo permanente nei tuoi spallacci la Soul of the Nurturer:\n\nLanciare Tocco Curativo o Nutrizione ti dà una probabilità del $N1% di ottenere mana pari al $N2% del costo base dell'incantesimo.", nil, 0x27373e53, nil, "um" },
  [1219930] = { "Infondi in modo permanente nei tuoi spallacci la Soul of the Tranquil:\n\nRiduce del $N1% il tempo di recupero di Tranquillità e ne aumenta le cure del $N2%.", nil, 0x75e99ee9, nil, "um" },
  [1219931] = { "Infondi in modo permanente nei tuoi spallacci la Soul of the Dreamwalker:\n\nI colpi critici dei tuoi incantesimi di cura attivano l'effetto Stato Onirico, che ti conferisce il $N1% della tua rigenerazione del mana durante il lancio per $D1.", nil, 0x59d8f6ae, nil, "um" },
  [1219932] = { "Infondi in modo permanente nei tuoi spallacci la Soul of the Grove Tender:\n\nI critici non periodici dei tuoi incantesimi riducono di $D1 il tempo di lancio del tuo prossimo Tocco Curativo, Ricrescita o Nutrizione.", nil, 0x1a48e166, nil, "um" },
  [1219933] = { "Infondi in modo permanente nei tuoi spallacci la Soul of the Feathered Sage:\n\nAumenta del $N1% le cure di Crescita Rigogliosa. Inoltre, Crescita Rigogliosa ora si può usare in Forma di Lunagufo, e in quella forma le sue cure aumentano di un ulteriore $N2%.", nil, 0x20efe98c, nil, "um" },
  [1219934] = { "Infondi in modo permanente nei tuoi spallacci la Soul of the Benevolent Seer:\n\nRiduce del $N1% il tempo di recupero dei tuoi incantesimi Pronto Ritorno e Innervazione.", nil, 0xe9fbb518, nil, "um" },
  [1219935] = { "Infondi in modo permanente nei tuoi spallacci la Soul of the Lifeweaver:\n\nLe tue cure critiche con Tocco Curativo, Ricrescita e Nutrizione curano istantaneamente il bersaglio di un ulteriore $N1% delle cure prodotte.", nil, 0xd7290ee6, nil, "um" },
  [1219936] = { "Infondi in modo permanente nei tuoi spallacci la Soul of the Illuminator:\n\nIl tuo Fuoco Fatato (Feral) aumenta anche del $N1% la probabilità d'impatto di tutti gli attacchi contro quel bersaglio per $D1.", nil, 0x31ebf6b1, nil, "um" },
  [1219937] = { "Infondi in modo permanente nei tuoi spallacci Soul of Predatory Instincts:\n\nI danni periodici di Graffio e Squarcio ora possono essere critici.", nil, 0xa4476103, nil, "um" },
  [1219938] = { "Infondi in modo permanente nei tuoi spallacci la Soul of the Ripper:\n\nI tuoi Squarcio e Morso Feroce hanno una probabilità del $N1% per punto combo speso di riportare la durata di Ruggito Selvaggio al valore iniziale.", nil, 0x5736589e, nil, "um" },
  [1219939] = { "Infondi in modo permanente nei tuoi spallacci la Soul of the Claw:\n\nAumenta di $D1 la durata di Graffio e del $N2% i suoi danni periodici.", nil, 0x93226e44, nil, "um" },
  [1219940] = { "Infondi in modo permanente nei tuoi spallacci la Soul of the Prideful:\n\nLa tua probabilità di colpo critico aumenta del $N1% mentre Furia della Tigre è attiva.", nil, 0x4357a4aa, nil, "um" },
  [1219941] = { "Infondi in modo permanente nei tuoi spallacci la Soul of the Barbaric:\n\nLe tue abilità Artigliata, Morso Feroce e Mangle (Cat) infliggono il $N1% di danni in più per ogni tuo effetto di sanguinamento sul bersaglio, fino a un massimo del $N2%.", nil, 0x5b2b9a65, nil, "um" },
  [1219942] = { "Infondi in modo permanente nei tuoi spallacci la Soul of the Frenetic:\n\nLa tua Artigliata non richiede più una posizione specifica, ma infligge il $N1% di danni in più se sei alle spalle del bersaglio.", nil, 0xadd75039, nil, "um" },
  [1219943] = { "Infondi in modo permanente nei tuoi spallacci la Soul of the Exsanguinator:\n\nI colpi critici di Dilaniamento, Artigliata e Morso Feroce fanno sanguinare il bersaglio, infliggendogli nei successivi $D1 il $N1% dei danni inflitti.", nil, 0x3eb7d73a, nil, "um" },
  [1219944] = { "Infondi in modo permanente nei tuoi spallacci la Soul of the Thornkeeper:\n\nDanni inflitti da Spine aumentati del $N1% e durata aumentata del $N2%.", nil, 0x96ee36a8, nil, "um" },
  [1219945] = { "Infondi in modo permanente nei tuoi spallacci la Soul of the Lunatic:\n\nAumenta la probabilità d'impatto con incantesimi e attacchi del $N1%.", nil, 0x0f335019, nil, "um" },
  [1219946] = { "Infondi in modo permanente nei tuoi spallacci la Soul of the Starcaller:\n\nRiduce del $N1% il tempo di recupero di Pioggia di Stelle.", nil, 0x73b11a4e, nil, "um" },
  [1219947] = { "Infondi in modo permanente nei tuoi spallacci la Soul of the Night:\n\nAumenta del $N1% i danni inflitti e il raggio dei danni delle stelle di Pioggia di Stelle e di Uragano.", nil, 0x096427d9, nil, "um" },
  [1219948] = { "Infondi in modo permanente nei tuoi spallacci la Soul of the Keepers:\n\nI tuoi lanci di Ira Silvana hanno il $N1% di probabilità di evocare un gruppo di $N2 treant che attaccano il tuo bersaglio per $D1.", nil, 0xd50f01e1, nil, "um" },
  [1219949] = { "Infondi in modo permanente nei tuoi spallacci la Soul of the Wrathful:\n\nI colpi critici della tua Ira Silvana hanno il $N1% di probabilità di far infliggere al tuo prossimo Fuoco Stellare il $N2% di danni in più, cumulabile fino a $N3 volte.", nil, 0x0f126c9c, nil, "um" },
  [1219950] = { "Infondi in modo permanente nei tuoi spallacci la Soul of the Graceful:\n\nIl tuo talento Grazia della Natura ottiene $N1 carica aggiuntiva ogni volta che si attiva.", nil, 0x98a17978, nil, "um" },
  [1219951] = { "Infondi in modo permanente nei tuoi spallacci la Soul of the Astral Ascendant:\n\nAumenta del $N1% il bonus ai danni critici di Fuoco Stellare, Cometa Arcana e Ira Silvana.", nil, 0x9de58a3d, nil, "um" },
  [1219952] = { "Infondi in modo permanente nei tuoi spallacci la Soul of the Cometcaller:\n\nRiduce il tempo di lancio e il tempo di recupero globale di Fuoco Stellare di $D1.", nil, 0x8c39a954, nil, "um" },
  [1219953] = { "Infondi in modo permanente nei tuoi spallacci la Soul of the Forest:\n\nAumenta la probabilità di critico di Ira Silvana del $N1%.", nil, 0xd7acb53d, nil, "um" },
  [1219954] = { "Infondi in modo permanente nei tuoi spallacci Soul of Animalistic Expertise:\n\nI tuoi attacchi in mischia hanno il $N1% di probabilità in meno di essere schivati o parati.", nil, 0xce82bd1f, nil, "um" },
  [1219955] = { "In questo spazio si può incidere l'anima di un combattente caduto.", nil, 0x12197f96, nil, "um" },
  [1219957] = { "Dopo aver cambiato postura, il costo in rabbia della tua prossima abilità offensiva si riduce di $N1.", nil, 0xc539fdf3, nil, "um" },
  [1219958] = { "Per $D1 dopo aver lasciato una postura, puoi usare le abilità che la richiedono come se fossi ancora in quella postura.", nil, 0xc53a0004, nil, "um" },
  [1219960] = { "Per i primi $D1 dopo aver attivato una postura, puoi ottenere un beneficio aggiuntivo:\n\nPostura da Battaglia/Gladiator Stance: danni inflitti aumentati del $N2%.\n\nPostura da Berserker: probabilità di critico aumentata del $N3%.\n\nPostura da Difesa: danni fisici subiti ridotti del $N4%.", nil, 0xc53a827a, nil, "um" },
  [1219962] = { "I colpi critici di Dominazione riportano al massimo la durata di Squartamento sul tuo bersaglio.", nil, 0xd6e870af, nil, "um" },
  [1219964] = { "Le tue abilità Assalto Eroico, Contusione e Dominazione infliggono il $N1% di danni in più.", nil, 0xd6e8f4b8, nil, "um" },
  [1219966] = { "I tuoi colpi di Contusione azzerano il tempo di recupero residuo delle abilità Assalto Mortale, Sete di Sangue e Colpo di Scudo.", nil, 0xd6e8f4b9, nil, "um" },
  [1219968] = { "Riduce del $N1% il tempo di recupero di Desiderio di Morte.", nil, 0x72700e72, nil, "um" },
  [1219970] = { "Infliggi il $N1% di danni in più mentre un nemico vicino è afflitto sia dal tuo Squartamento sia dalle tue Ferite Profonde.", nil, 0x72700eef, nil, "um" },
  [1219972] = { "Aumenta l'indice di blocco con lo scudo di $N1.", nil, 0xc539fd73, nil, "um" },
  [1219974] = { "Ottieni $N1 rabbia aggiuntiva ogni volta che subisci danni o infliggi danni con l'attacco automatico.", nil, 0xc539fd74, nil, "um" },
  [1219976] = { "Aumenta di un ulteriore $N1% tutta la minaccia che generi in Postura da Difesa e del $N2% tutti i danni che infliggi in Gladiator Stance.", nil, 0xc539fdf2, nil, "um" },
  [1219978] = { "Ottieni $N1 rabbia ogni volta che pari o che uno dei tuoi attacchi viene parato.", nil, 0xd6e8702f, nil, "um" },
  [1219980] = { "Rivincita ti conferisce anche Raffica di Colpi, che aumenta la tua velocità d'attacco del $N1% per i prossimi $N2 colpi.", nil, 0xd6e87031, nil, "um" },
  [1219982] = { "Quando il tuo bersaglio para un attacco, esegui istantaneamente una Reazione contro di lui che infligge il $N1% dei danni dell'arma. Reazione non può essere schivata, bloccata o parata, ma può verificarsi solo una volta ogni $D1 per bersaglio.", nil, 0xd6e87033, nil, "um" },
  [1219984] = { "Riduce del $N1% il tempo di recupero di Schianto del Tuono.", nil, 0x72700eec, nil, "um" },
  [1219986] = { "Il tuo Colpo di Scudo genera il $N1% di minaccia in più e il suo tempo di recupero si azzera se viene schivato, parato o bloccato.", nil, 0x72700eee, nil, "um" },
  [1219988] = { "Riduce il tempo di recupero di Colpo di Scudo di $D1.", nil, 0xd6e97bcd, nil, "um" },
  [1219990] = { "Riduce il tempo di recupero di Rabbia del Sangue di $D1 mentre sei in Gladiator Stance.", nil, 0xd6e97bce, nil, "um" },
  [1219992] = { "Riduce del $N1% il tempo di recupero di Onda d'Urto.", nil, 0x72700ef1, nil, "um" },
  [1219994] = { "Finta conferisce anche Elusione per $D1, riducendo del $N2% tutti i danni subiti dagli attacchi ad area dei non giocatori.", nil, 0xc5393356, nil, "um" },
  [1219996] = { "Aumenta del $N1% il bonus ai danni critici dei tuoi veleni.", nil, 0xc53933d9, nil, "um" },
  [1219998] = { "Le tue mosse risolutive hanno una probabilità del $N1% per punto combo di azzerare il costo in energia della tua prossima abilità.", nil, 0xc5393457, nil, "um" },
})
